"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { api, type ApiResponse } from "@/lib/api";
import { useAuthStore } from "@/stores/authStore";
import { isMartRole } from "@/stores/authStore";
import { ShoppingBag, Loader2 } from "lucide-react";

const schema = z.object({
  email: z.string().email("Invalid email"),
  password: z.string().min(1, "Password required"),
});

type FormData = z.infer<typeof schema>;

export default function LoginPage() {
  const router = useRouter();
  const setCredentials = useAuthStore((s) => s.setCredentials);
  const token = useAuthStore((s) => s.token);
  const user = useAuthStore((s) => s.user);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (token && user && isMartRole(user.role)) {
      router.replace("/dashboard");
    }
  }, [token, user, router]);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: { email: "", password: "" },
  });

  const onSubmit = async (data: FormData) => {
    setError(null);
    try {
      const res = await api.post<ApiResponse<{ user: unknown; accessToken: string; refreshToken: string }>>(
        "/auth/login",
        data
      );
      const { user, accessToken, refreshToken } = res.data.data;
      const u = user as { id: string; email: string; name: string; role: string; storeId?: string | null };
      if (!isMartRole(u.role)) {
        setError("Access denied. Use the Mart dashboard with a Manager or Merchant account.");
        return;
      }
      setCredentials({
        accessToken,
        refreshToken,
        user: {
          id: u.id,
          email: u.email,
          name: u.name,
          role: u.role,
          storeId: u.storeId ?? null,
        },
      });
      router.replace("/dashboard");
      router.refresh();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Login failed");
    }
  };

  return (
    <div className="rounded-2xl border border-[var(--border)] bg-[var(--card-bg)] shadow-lg p-8">
      <div className="flex flex-col items-center mb-8">
        <div className="w-14 h-14 rounded-full bg-[var(--primary-light)] flex items-center justify-center mb-4">
          <ShoppingBag className="w-7 h-7 text-[var(--primary)]" />
        </div>
        <h1 className="text-2xl font-bold text-[var(--foreground)]">ZimCart Mart</h1>
        <p className="text-sm text-slate-500 mt-1">Sign in to manage your store</p>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
        {error && (
          <div className="text-sm text-red-600 bg-red-50 border border-red-200 rounded-lg px-3 py-2">
            {error}
          </div>
        )}
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
          <input
            {...register("email")}
            type="email"
            autoComplete="email"
            className="w-full rounded-xl border border-slate-200 px-4 py-3 focus:border-[var(--primary)] focus:ring-1 focus:ring-[var(--primary)] outline-none"
            placeholder="you@store.com"
          />
          {errors.email && (
            <p className="text-red-500 text-xs mt-1">{errors.email.message}</p>
          )}
        </div>
        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Password</label>
          <input
            {...register("password")}
            type="password"
            autoComplete="current-password"
            className="w-full rounded-xl border border-slate-200 px-4 py-3 focus:border-[var(--primary)] focus:ring-1 focus:ring-[var(--primary)] outline-none"
            placeholder="••••••••"
          />
          {errors.password && (
            <p className="text-red-500 text-xs mt-1">{errors.password.message}</p>
          )}
        </div>
        <button
          type="submit"
          disabled={isSubmitting}
          className="w-full bg-[var(--primary)] hover:bg-[var(--primary-hover)] text-white font-semibold py-3 rounded-xl flex items-center justify-center gap-2 transition-colors disabled:opacity-70"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="w-5 h-5 animate-spin" />
              Signing in...
            </>
          ) : (
            "Sign in"
          )}
        </button>
      </form>
    </div>
  );
}
